solutions.naive:
class Solution:
    def getHint(self, secret: str, guess: str) -> str:
        n = len(secret)
        bulls = 0
        used_secret = [False] * n
        used_guess = [False] * n
        for i in range(n):
            if secret[i] == guess[i]:
                bulls += 1
                used_secret[i] = True
                used_guess[i] = True
        cows = 0
        for i in range(n):
            if used_guess[i]:
                continue
            for j in range(n):
                if not used_secret[j] and guess[i] == secret[j]:
                    used_secret[j] = True
                    cows += 1
                    break
        return str(bulls) + "A" + str(cows) + "B"

solutions.better:
class Solution:
    def getHint(self, secret, guess):
        bulls = 0
        secret_count = [0] * 10
        guess_count = [0] * 10
        for s, g in zip(secret, guess):
            if s == g:
                bulls += 1
            else:
                secret_count[ord(s) - ord('0')] += 1
                guess_count[ord(g) - ord('0')] += 1
        cows = sum(min(secret_count[i], guess_count[i]) for i in range(10))
        return str(bulls) + "A" + str(cows) + "B"

solutions.optimal:
class Solution:
    def getHint(self, secret, guess):
        bulls = 0
        cows = 0
        balance = [0] * 10
        for s, g in zip(secret, guess):
            if s == g:
                bulls += 1
            else:
                si = ord(s) - ord('0')
                gi = ord(g) - ord('0')
                if balance[si] < 0:
                    cows += 1
                if balance[gi] > 0:
                    cows += 1
                balance[si] += 1
                balance[gi] -= 1
        return str(bulls) + "A" + str(cows) + "B"

